import networkx as nx
import itertools

def get_king_torus_graph(n):
    G = nx.Graph()
    nodes = list(itertools.product(range(n), range(n)))
    G.add_nodes_from(nodes)
    for x, y in nodes:
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx.add_edge(G, (x, y), ((x + dx) % n, (y + dy) % n))
    return G

