# Since nx.is_k_colorable is not available, let's use a simple backtracking search
def can_color(G, k):
    nodes = list(G.nodes())
    color = {}
    def backtrack(node_idx):
        if node_idx == len(nodes):
            return True
        u = nodes[node_idx]
        # Try all colors
        neighbor_colors = {color[v] for v in G.neighbors(u) if v in color}
        for c in range(k):
            if c not in neighbor_colors:
                color[u] = c
                if backtrack(node_idx + 1):
                    return True
                del color[u]
        return False
    return backtrack(0)

for n in [1, 2, 3, 4, 5]:
    G = get_king_torus_graph(n)
    # Special case: n=1, the node is its own neighbor?
    # The problem says "distinct neighboring points".
    # If n=1, there are no distinct points. But the periodicity says (0,0) and (1,0) must be the same color.
    # But (0,0) and (1,0) are the same point if N=1.
    # Let's ignore N=1.
    if n < 2: continue
    for k in range(1, 10):
        if can_color(G, k):
            print(f"N={n}, chromatic number={k}")
            break

