import networkx as nx
import itertools

def get_king_torus_graph(n):
    G = nx.Graph()
    nodes = list(itertools.product(range(n), range(n)))
    G.add_nodes_from(nodes)
    for x, y in nodes:
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                u = (x, y)
                v = ((x + dx) % n, (y + dy) % n)
                if u != v:
                    G.add_edge(u, v)
    return G

def can_color(G, k):
    # Using a more efficient coloring check from networkx
    # but nx.coloring doesn't have a simple is_k_colorable.
    # Let's use the backtracking with a simple heuristic (most constrained variable).
    nodes = list(G.nodes())
    color = {}

    def get_possible_colors(u):
        neighbor_colors = {color[v] for v in G.neighbors(u) if v in color}
        return [c for c in range(k) if c not in neighbor_colors]

    def backtrack():
        if len(color) == len(nodes):
            return True

        # MRV heuristic
        uncolored = [u for u in nodes if u not in color]
        u = min(uncolored, key=lambda x: len(get_possible_colors(x)))

        possible = get_possible_colors(u)
        for c in possible:
            color[u] = c
            if backtrack():
                return True
            del color[u]
        return False

    return backtrack()

